<?php require __DIR__.'/_guard.php';$rows=$conn->query('SELECT product_code,product_name,quantity,reorder_level FROM products WHERE quantity<=reorder_level ORDER BY quantity ASC');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Low Stock</title><link rel="stylesheet" href="../assets/css/modern.css"></head><body><main class="page"><header class="topbar"><div><a class="brand" href="dashboard.php">Fresh<span>Mart</span></a><h1>Low-stock alerts</h1></div><a class="btn" href="dashboard.php">Dashboard</a></header><nav class="nav"><a href="dashboard.php">Overview</a><a href="stock.php">Stock In / Out</a><a href="history.php">Stock history</a><a href="low_stock.php">Low stock</a></nav><section class="panel table-wrap"><table><thead><tr><th>Code</th><th>Product</th><th>Available</th><th>Reorder level</th><th>Alert</th></tr></thead><tbody><?php if($rows&&$rows->num_rows):while($r=$rows->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['product_code'])?></td><td><?=htmlspecialchars($r['product_name'])?></td><td><?=$r['quantity']?></td><td><?=$r['reorder_level']?></td><td><span class="badge warn">Reorder needed</span></td></tr><?php endwhile;else:?><tr><td colspan="5">All products are above their reorder levels.</td></tr><?php endif;?></tbody></table></section></main></body></html>
